UnboundLocalError.example:
count = 0
def add():
    count = count + 1   # 'count' is local here, and empty
def add_ok():
    global count
    count = count + 1

IndentationError.example:
def greet():
print("hi")       # not indented, so it is not inside greet

def greet_ok():
    print("hi")   # four spaces: inside the function

KeyError.example:
ages = {"sam": 12}
print(ages["Sam"])          # capital S is a different key
print(ages.get("Sam", 0))   # .get returns a default instead of failing

EOFError.example:
while True:
    line = input()   # nothing left to read on the second turn
# Ask once, or stop when the answer is empty.

RecursionError.example:
def count(n):
    return count(n - 1)   # never stops

def count_ok(n):
    if n <= 0:
        return 0          # the base case
    return count_ok(n - 1)

NotImplementedError.example:
class Shape:
    def area(self):
        raise NotImplementedError   # subclasses must provide this

class Square(Shape):
    def area(self):
        return self.side ** 2
